import { prepareGroupBuyOrder } from "@/lib/group-buy/commerce";

async function createTindahanOrder(body: any) {
  const customerName = String(body.customerName || "").trim();
  const customerPhone = String(body.customerPhone || "").trim();
  const deliveryAddress = String(body.deliveryAddress || "").trim();
  const city = String(body.city || "").trim();
  const province = String(body.province || "").trim();
  const region = String(body.region || province).trim();
  const items = Array.isArray(body.items) ? body.items : [];
  if (!customerName || !customerPhone || !deliveryAddress || !city || !province) {
    return NextResponse.json({ success: false, error: "Name, phone, address, city, and province are required." }, { status: 400, headers: corsHeaders() });
  }
  if (!items.length || items.length > 100) {
    return NextResponse.json({ success: false, error: "Add between 1 and 100 cart lines." }, { status: 400, headers: corsHeaders() });
  }
  if (body.shipmentPreference !== "together" && body.shipmentPreference !== "separate") {
    return NextResponse.json({ success: false, error: "Choose a shipment option." }, { status: 400, headers: corsHeaders() });
  }

  const proof = typeof body.imageData === "string"
    ? body.imageData.match(/^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/=]+)$/)
    : null;
  if (!proof || proof[2].length > 4_200_000) {
    return NextResponse.json({ success: false, error: "Upload a PNG, JPG, or WebP receipt under 3 MB." }, { status: 400, headers: corsHeaders() });
  }

  try {
    const buffer = Buffer.from(proof[2], "base64");
    if (!buffer.length || buffer.length > 3 * 1024 * 1024) {
      return NextResponse.json({ success: false, error: "Receipt must be under 3 MB." }, { status: 400, headers: corsHeaders() });
    }
    const mimeType = proof[1];
    const extension = mimeType === "image/jpeg" ? "jpg" : mimeType.split("/")[1];
    const originalName = typeof body.imageName === "string" ? body.imageName.replace(/\.[^.]+$/, "") : "receipt";
    const safeName = originalName.replace(/[^a-zA-Z0-9_-]/g, "_").slice(-80) || "receipt";

    const productIds: string[] = [...new Set<string>(items.map((item: any) => String(item?.productId || "")).filter((id: string) => id.length > 0))];
    const [dbProducts, shippingRecord] = await Promise.all([
      productIds.length ? db.query.products.findMany({ where: inArray(products.id, productIds) }) : Promise.resolve([]),
      db.query.appSettings.findFirst({ where: eq(appSettings.key, "shipping_config") }),
    ]);
    const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
    const dbBatches = batchIds.length
      ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
      : [];
    const prepared = prepareGroupBuyOrder({
      items,
      shipmentPreference: body.shipmentPreference,
      region,
      shippingConfig: (shippingRecord?.value ?? {}) as Record<string, Record<string, number>>,
      products: new Map(dbProducts.map((product) => [product.id, product])),
      batches: new Map(dbBatches.map((batch) => [batch.id, batch])),
    });

    const uploadedProof = await uploadPaymentProof(buffer, mimeType, `${Date.now()}_${safeName}.${extension}`);

    const latestOrder = await db.query.orders.findFirst({ orderBy: [desc(orders.id)], columns: { id: true } });
    const orderNumber = `TT-${new Date().getFullYear()}-${String((latestOrder?.id ?? 0) + 1).padStart(5, "0")}-${randomUUID().slice(0, 4).toUpperCase()}`;
    const orderData = {
      orderNumber,
      shipmentPreference: body.shipmentPreference,
      customerName,
      customerPhone,
      customerEmail: String(body.customerEmail || "").trim().slice(0, 254),
      deliveryAddress,
      city,
      province,
      postalCode: String(body.postalCode || "").trim(),
      shippingMethod: `Tindahan ni Tinapa · ${province}`,
      shippingFee: prepared.shippingFee,
      paymentMethod: String(body.paymentMethod || "GCash").trim().slice(0, 80),
      paymentProofFileId: uploadedProof.fileId,
      subtotal: prepared.subtotal,
      total: prepared.total,
      notes: String(body.notes || "").trim().slice(0, 500),
    };
    const result = await db.execute(sql`
      SELECT create_tindahan_order(
        ${JSON.stringify(orderData)}::jsonb,
        ${JSON.stringify(prepared.shipments)}::jsonb,
        ${JSON.stringify(prepared.items)}::jsonb
      ) AS order_result
    `);
    const created = result.rows[0]?.order_result as { id: number; orderNumber: string } | undefined;
    if (!created) throw new Error("Order could not be saved.");

    try {
      const { sendPushNotificationToAll } = await import("@/lib/push/service");
      sendPushNotificationToAll({
        title: "New Tindahan ni Tinapa order",
        body: `Order #${created.orderNumber} from ${customerName}`,
        url: "/admin/group-buy/orders",
        tag: `order-${created.id}`,
      }).catch((error) => console.warn("Group-buy notification failed:", error));
    } catch (error) {
      console.warn("Could not load push service:", error);
    }

    return NextResponse.json({ success: true, orderId: created.id, orderNumber: created.orderNumber }, { status: 201, headers: corsHeaders() });
  } catch (error: any) {
    const message = error?.message || "Could not place order.";
    const clientError = /cart is empty|invalid cart item|not enough stock|no longer available|batch.*closed|shipping is unavailable|valid shipping region|maximum quantity|supported payment limit|invalid price|price .* too high/i.test(message);
    return NextResponse.json({ success: false, error: message }, { status: clientError ? 400 : 500, headers: corsHeaders() });
  }
}

// CORS Headers helper
function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
