}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => null);

    if (!body) {
      return NextResponse.json(
        { success: false, error: "Invalid JSON payload." },
        { status: 400, headers: corsHeaders() }
      );
    }

    if (body.storefrontKey === "tindahan") return await createTindahanOrder(body);

    // Extract fields with alias fallback support
    const customerName = String(
      body.customerName || body.name || body.recipient || ""
    ).trim();
    const customerPhone = String(
      body.customerPhone || body.phone || body.contactNumber || ""
    ).trim();
    const deliveryAddress = String(
      body.deliveryAddress || body.address || body.street || ""
    ).trim();
    const city = String(body.city || "Metro Manila").trim();
    const province = String(body.province || "Metro Manila").trim();
    const customerEmail = body.customerEmail || body.email || null;
    const postalCode = body.postalCode || null;

    const shippingMethodName = String(
      body.shippingMethod || body.shipping || "Standard Shipping"
    ).trim();
    const rawShippingFee = Number(body.shippingFee ?? 0);

    const paymentMethod = String(body.paymentMethod || "GCash").trim();
    const notes = body.notes || body.specialInstructions || body.remarks || null;

    // Validate required customer info
    if (!customerName) {
      return NextResponse.json(
        { success: false, error: "customerName is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!customerPhone) {
      return NextResponse.json(
        { success: false, error: "customerPhone is required." },
        { status: 400, headers: corsHeaders() }
      );
    }
    if (!deliveryAddress) {
      return NextResponse.json(
        { success: false, error: "deliveryAddress is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Validate items array
    const rawItems = Array.isArray(body.items) ? body.items : [];
    if (rawItems.length === 0) {
      return NextResponse.json(
        { success: false, error: "At least one item is required." },
        { status: 400, headers: corsHeaders() }
      );
    }

    // Process & calculate items
    const parsedLineItems: Array<{
      productId: string | null;
      productName: string;
      unitPrice: number;
      quantity: number;
      subtotal: number;
    }> = [];

    let calculatedSubtotalInCents = 0;
    let totalItemCount = 0;

    for (const rawItem of rawItems) {
      const quantity = Math.max(1, Number(rawItem.quantity || 1));
      totalItemCount += quantity;

      const rawItemName = String(
        rawItem.name || rawItem.productName || rawItem.id || "Product Item"
      ).trim();

      // Lookup product reference if available
      const matched =
        (rawItem.id ? getProductById(rawItem.id) : undefined) ||
