    const calculatedTieredShippingFeePesos = calculateShippingFee(
      shippingMethodName || province || city,
      totalItemCount
    );

    // Determine final shipping fee in cents
    const shippingFeeInCents =
      rawShippingFee > 0
        ? rawShippingFee < 10000
          ? Math.round(rawShippingFee * 100)
          : Math.round(rawShippingFee)
        : Math.round(calculatedTieredShippingFeePesos * 100);

