      orderBy: [asc(products.sortOrder), asc(products.createdAt)],
    });

    if (storefront === "tindahan") {
      const batchIds = [...new Set(dbProducts.map((product) => product.batchId).filter((id): id is number => id !== null))];
      const dbBatches = batchIds.length
        ? await db.query.groupBuyBatches.findMany({ where: inArray(groupBuyBatches.id, batchIds) })
        : [];
      const now = Date.now();
      const batches = dbBatches.map((batch) => ({
        ...batch,
        status: batch.status === "open" && batch.deadline.getTime() <= now ? "closed" : batch.status,
      }));
      const shippingConfigRecord = await db.query.appSettings.findFirst({
        where: eq(appSettings.key, "shipping_config"),
      });

      return NextResponse.json({
        categories: dbCategories.map((category) => ({
          id: category.id,
          name: category.name,
          icon: category.icon || "📦",
