          categoryId: product.categoryId,
          name: product.name,
          fullName: product.fullName,
          price: product.price,
          compareAtPrice: product.compareAtPrice,
          description: product.description,
          imageUrl: product.imageUrl,
          emoji: product.emoji || "📦",
          stock: product.stock,
          kind: product.kind,
          batchId: product.batchId,
          batch: batches.find((batch) => batch.id === product.batchId) ?? null,
        })),
        batches,
        shippingConfig: shippingConfigRecord?.value ?? {},
      }, {
        status: 200,
        headers: { ...corsHeaders, "Cache-Control": "public, s-maxage=30, stale-while-revalidate=60" },
      });
    }

    // Group products by categoryId
    const productsByCat = new Map<string, typeof dbProducts>();
    for (const prod of dbProducts) {
      if (!prod.categoryId) continue;
      if (!productsByCat.has(prod.categoryId)) {
        productsByCat.set(prod.categoryId, []);
      }
      productsByCat.get(prod.categoryId)!.push(prod);
    }

    // 3. Assemble category payload matching products.json 1:1
