    // 4. Fetch shipping_config from appSettings
    const shippingConfigRecord = await db.query.appSettings.findFirst({
      where: eq(appSettings.key, "shipping_config"),
    });

    if (shippingConfigRecord?.value) {
      catalog.push(shippingConfigRecord.value as any);
    }

    return NextResponse.json(catalog, {
