} from "@/lib/validation/schemas";
import { revalidatePath } from "next/cache";

async function requireAdmin() {
  const session = await auth();
  if (!session?.user) {
    throw new Error("Unauthorized");
  }
  return session;
}

const STATUS_LABELS: Record<string, string> = {
  pending_payment: "Pending Payment",
  payment_verification: "Payment Verification",
  paid: "Paid",
  processing: "Processing",
  ready_to_ship: "Ready to Ship",
  shipped: "Shipped",
  completed: "Completed",
  cancelled: "Cancelled",
};

// ============================================================
// CONFIRM PAYMENT
// ============================================================

export async function confirmPayment(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const parsed = confirmPaymentSchema.safeParse({
    orderId: Number(formData.get("orderId")),
  });
  if (!parsed.success) return { success: false, error: "Invalid request." };

  const { orderId } = parsed.data;

  const order = await db.query.orders.findFirst({
    where: (o, { eq }) => eq(o.id, orderId),
  });

  if (!order) return { success: false, error: "Order not found." };

  if (order.storefrontKey === "tindahan") {
    try {
      await db.execute(sql`SELECT confirm_tindahan_payment(${orderId})`);
    } catch (error: any) {
      const message = String(error?.message || "");
      if (message.includes("ON_HAND_STOCK_INSUFFICIENT")) {
        return { success: false, error: "Payment not confirmed. On-hand stock is no longer sufficient." };
      }
      console.error("Tindahan payment confirmation failed:", error);
      return { success: false, error: "Payment could not be confirmed. Check the group-buy migration and try again." };
    }

    revalidatePath("/");
    revalidatePath("/admin");
    revalidatePath("/admin/orders");
    revalidatePath("/admin/group-buy");
    revalidatePath("/admin/group-buy/orders");
    revalidatePath(`/admin/orders/${orderId}`);
    return { success: true };
  }

  // Update order status
  await db
    .update(orders)
    .set({
      paymentStatus: "paid",
      orderStatus: "processing",
      updatedAt: new Date(),
    })
    .where(eq(orders.id, orderId));

  // Log timeline events
  await db.insert(orderEvents).values([
    {
      orderId,
      eventType: "payment_confirmed",
      description: "Payment confirmed by seller.",
    },
    {
      orderId,
      eventType: "order_processing",
