export async function updateOrderStatus(
  formData: FormData
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const rawNotes = formData.get("notes");
  const notes =
    rawNotes && typeof rawNotes === "string" && rawNotes.trim() !== ""
      ? rawNotes.trim()
      : undefined;

  const parsed = updateOrderStatusSchema.safeParse({
    orderId: Number(formData.get("orderId")),
    orderStatus: formData.get("orderStatus"),
    notes,
  });
  if (!parsed.success) {
    console.error("updateOrderStatus validation failure:", parsed.error.format());
    return { success: false, error: "Invalid status or parameters." };
  }

  const { orderId, orderStatus } = parsed.data;

  return quickChangeOrderStatus(orderId, orderStatus, notes);
}

export async function quickChangeOrderStatus(
  orderId: number,
  orderStatus: string,
  notes?: string
): Promise<{ success: boolean; error?: string }> {
  await requireAdmin();

  const currentOrder = await db.query.orders.findFirst({ where: eq(orders.id, orderId) });
  if (!currentOrder) return { success: false, error: "Order not found." };
  if (
    currentOrder.storefrontKey === "tindahan" &&
    currentOrder.paymentStatus !== "paid" &&
    (orderStatus === "paid" || orderStatus === "processing")
  ) {
    return { success: false, error: "Verify the receipt before marking this order paid." };
  }

  const updateData: Record<string, any> = {
    orderStatus,
    updatedAt: new Date(),
  };

  if (notes !== undefined) {
    updateData.notes = notes;
  }

  if (orderStatus === "paid" || orderStatus === "processing") {
    updateData.paymentStatus = "paid";
  }

  await db.update(orders).set(updateData).where(eq(orders.id, orderId));

  await db.insert(orderEvents).values({
    orderId,
    eventType: `status_updated_${orderStatus}`,
    description: `Order status updated to: ${STATUS_LABELS[orderStatus] ?? orderStatus}.`,
  });

  revalidatePath("/");
  revalidatePath("/admin");
  revalidatePath("/admin/orders");
  revalidatePath(`/admin/orders/${orderId}`);

  return { success: true };
}

