export async function toggleProductAvailability(
  id: string,
  currentStatus: boolean
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const newStatus = !currentStatus;

    await db
      .update(products)
      .set({ isAvailable: newStatus })
      .where(and(eq(products.id, id), eq(products.storefrontKey, "main")));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, isAvailable: newStatus };
  } catch (error: any) {
    console.error("toggleProductAvailability error:", error);
    return {
      success: false,
      error: error?.message || "Failed to toggle product availability",
    };
  }
}
