type ShippingRates = Record<string, Record<string, number>>;

function isOrderable(batch: CommerceBatch | undefined, now: Date) {
  return Boolean(
    batch &&
      batch.status === "open" &&
      new Date(batch.deadline).getTime() > now.getTime()
  );
}

function getShippingRate(config: ShippingRates, region: string, quantity: number) {
  const normalized = region.trim().toLowerCase();
  if (!["luzon", "visayas", "mindanao", "other"].includes(normalized)) {
    throw new Error("Choose a valid shipping region.");
  }
  let rates = config[normalized];
  if (!rates) throw new Error("Shipping is unavailable for this region.");
  const fee = quantity <= 1 ? rates["1"] ?? 0 : quantity === 2 ? rates["2"] ?? 0 : rates.max ?? 0;
  if (!Number.isSafeInteger(fee) || fee < 0) throw new Error("Shipping is unavailable for this region.");
  return fee;
}

