CREATE OR REPLACE FUNCTION create_tindahan_order(p_order jsonb, p_shipments jsonb, p_items jsonb)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  v_order_id integer;
  v_shipment record;
  v_item record;
BEGIN
  INSERT INTO orders (
    order_number, storefront_key, shipment_preference, customer_name, customer_phone,
    customer_email, delivery_address, city, province, postal_code, shipping_method,
    shipping_fee, payment_method, payment_proof_file_id, payment_status, order_status,
    subtotal, total, notes, created_at, updated_at
  ) VALUES (
    p_order->>'orderNumber', 'tindahan', p_order->>'shipmentPreference',
    p_order->>'customerName', p_order->>'customerPhone', NULLIF(p_order->>'customerEmail', ''),
    p_order->>'deliveryAddress', p_order->>'city', p_order->>'province',
    NULLIF(p_order->>'postalCode', ''), p_order->>'shippingMethod',
    (p_order->>'shippingFee')::integer, p_order->>'paymentMethod', p_order->>'paymentProofFileId',
    'under_verification', 'payment_verification', (p_order->>'subtotal')::integer,
    (p_order->>'total')::integer, NULLIF(p_order->>'notes', ''), now(), now()
  ) RETURNING id INTO v_order_id;

  FOR v_shipment IN
    SELECT value FROM jsonb_array_elements(p_shipments)
  LOOP
    INSERT INTO order_shipments(order_id, kind, batch_id, shipping_fee)
    VALUES (
      v_order_id,
      (v_shipment.value->>'kind')::shipment_kind,
      NULLIF(v_shipment.value->>'batchId', '')::integer,
      (v_shipment.value->>'shippingFee')::integer
    );

  END LOOP;

  FOR v_item IN
    SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO order_items (
      order_id, product_id, product_kind, batch_id, shipment_id,
      product_name, unit_price, quantity, subtotal
    ) VALUES (
      v_order_id, v_item.value->>'productId', (v_item.value->>'productKind')::product_kind,
      NULLIF(v_item.value->>'batchId', '')::integer,
      (SELECT id FROM order_shipments WHERE order_id = v_order_id
       ORDER BY id OFFSET (v_item.value->>'shipmentIndex')::integer LIMIT 1),
      v_item.value->>'productName', (v_item.value->>'unitPrice')::integer,
      (v_item.value->>'quantity')::integer, (v_item.value->>'subtotal')::integer
    );
  END LOOP;

  INSERT INTO order_events(order_id, event_type, description) VALUES
    (v_order_id, 'order_submitted', 'Tindahan ni Tinapa group-buy order submitted.'),
    (v_order_id, 'payment_proof_uploaded', 'Payment proof attached with order.');

  RETURN jsonb_build_object('id', v_order_id, 'orderNumber', p_order->>'orderNumber');
END;
$$;
