CREATE OR REPLACE FUNCTION confirm_tindahan_payment(p_order_id integer)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE
  v_storefront storefront_key;
  v_payment_status payment_status;
BEGIN
  SELECT storefront_key, payment_status INTO v_storefront, v_payment_status
  FROM orders WHERE id = p_order_id FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND'; END IF;
  IF v_storefront <> 'tindahan' THEN RAISE EXCEPTION 'NOT_TINDAHAN_ORDER'; END IF;
  IF v_payment_status = 'paid' THEN RETURN 'already_paid'; END IF;
  IF v_payment_status <> 'under_verification' THEN RAISE EXCEPTION 'PAYMENT_NOT_UNDER_VERIFICATION'; END IF;

  PERFORM p.id
  FROM products p
  JOIN (
    SELECT product_id, sum(quantity)::integer AS quantity
    FROM order_items
    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
    GROUP BY product_id
  ) requested ON requested.product_id = p.id
  ORDER BY p.id
  FOR UPDATE OF p;

  IF EXISTS (
    SELECT 1
    FROM products p
    JOIN (
      SELECT product_id, sum(quantity)::integer AS quantity
      FROM order_items
      WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
      GROUP BY product_id
    ) requested ON requested.product_id = p.id
    WHERE p.stock < requested.quantity
  ) THEN RAISE EXCEPTION 'ON_HAND_STOCK_INSUFFICIENT'; END IF;

  UPDATE products p
  SET stock = p.stock - requested.quantity
  FROM (
    SELECT product_id, sum(quantity)::integer AS quantity
    FROM order_items
    WHERE order_id = p_order_id AND product_kind = 'on_hand' AND product_id IS NOT NULL
    GROUP BY product_id
  ) requested
  WHERE requested.product_id = p.id;

  UPDATE orders
  SET payment_status = 'paid', order_status = 'processing', updated_at = now()
  WHERE id = p_order_id;

  INSERT INTO order_events(order_id, event_type, description) VALUES
    (p_order_id, 'payment_confirmed', 'Payment confirmed by seller.'),
    (p_order_id, 'order_processing', 'Order is now being processed.');

  RETURN 'confirmed';
END;
$$;
